// Cargo-only build script. In the Chromium fork the bridge is generated by
// GN's `cxx_bindings` and this file is unused.

fn main() {
    // Emit the header at the same include path Chromium's GN uses
    // ("components/modal_browser/ffi/src/lib.rs.h"), so the C++ host code
    // compiles unchanged in both builds.
    cxx_build::CFG.include_prefix = "components/modal_browser/ffi";
    cxx_build::bridge("src/lib.rs")
        .std("c++20")
        .compile("modal_browser_ffi_bridge");
    println!("cargo:rerun-if-changed=src/lib.rs");
}
